package toast

props {
  // Class adds classes to the root element.
  Class    string = ""
  // Children is the toasts the toaster holds at render. Nil renders an empty toaster.
  Children gx.Node = nil
  // Attrs adds HTML attributes to the root element.
  Attrs    gx.Attrs = nil
}

<div id="gx-toaster" role="region" aria-label="Notifications" aria-live="polite" data-gx-toaster class={gx.Cx("fixed right-4 bottom-4 z-50 flex w-[356px] max-w-[calc(100vw-2rem)] flex-col gap-3", p.Class)} {...p.Attrs}>{p.Children}</div>

package toast

props {
  // Toast is the pushed toast: its text, kind, description, action and timing.
  Toast gx.ToastPatch
  // Class adds classes to the root element.
  Class string = ""
  // Attrs adds HTML attributes to the root element.
  Attrs gx.Attrs = nil
}

<div class={gx.Cx("flex w-full items-start gap-2 rounded-lg border border-border bg-popover p-4 text-sm text-popover-foreground shadow-lg transition-[opacity,translate] duration-200 ease-out starting:translate-y-2 starting:opacity-0 data-[closing]:pointer-events-none data-[closing]:translate-x-4 data-[closing]:opacity-0 motion-reduce:transition-none", p.Class)} {...gx.ToastAttrs(p.Toast)} {...p.Attrs}>
  if p.icon() != "" {
    {gx.Icon(p.icon(), gx.IconProps{Class: p.iconClass()})}
  }
  <div class="grid min-w-0 flex-1 gap-0.5">
    <div class="leading-5 font-medium">{p.Toast.Text}</div>
    if p.Toast.Description != "" {
      <div class="leading-5 text-muted-foreground">{p.Toast.Description}</div>
    }
  </div>
  if p.Toast.Action.Method != "" {
    <button type="button" data-gx-close class="inline-flex h-6 shrink-0 items-center rounded-md bg-primary px-2 text-xs font-medium text-primary-foreground outline-none hover:bg-primary/90 focus-visible:ring-[3px] focus-visible:ring-ring/50" {...p.invoke()}>{p.Toast.Action.Label}</button>
  } else if p.Toast.Action.Label != "" {
    <a href={p.Toast.Action.URL} class="inline-flex h-6 shrink-0 items-center rounded-md bg-primary px-2 text-xs font-medium text-primary-foreground outline-none hover:bg-primary/90 focus-visible:ring-[3px] focus-visible:ring-ring/50">{p.Toast.Action.Label}</a>
  }
  <button type="button" data-gx-close aria-label="Close" class="-my-0.5 -mr-1 inline-flex size-6 shrink-0 items-center justify-center rounded-md text-muted-foreground outline-none hover:bg-accent hover:text-accent-foreground focus-visible:ring-[3px] focus-visible:ring-ring/50">
    {gx.Icon(iconX, gx.IconProps{Class: "size-4"})}
  </button>
</div>

package toast

import "github.com/alternayte/gx"

// The icon bodies come from Lucide (https://lucide.dev), ISC License,
// Copyright (c) Lucide Contributors.
const (
	iconCircleCheck   = `<circle cx="12" cy="12" r="10"/><path d="m9 12 2 2 4-4"/>`
	iconInfo          = `<circle cx="12" cy="12" r="10"/><path d="M12 16v-4"/><path d="M12 8h.01"/>`
	iconTriangleAlert = `<path d="m21.73 18-8-14a2 2 0 0 0-3.48 0l-8 14A2 2 0 0 0 4 21h16a2 2 0 0 0 1.73-3"/><path d="M12 9v4"/><path d="M12 17h.01"/>`
	iconOctagonX      = `<path d="m15 9-6 6"/><path d="M2.586 16.726A2 2 0 0 1 2 15.312V8.688a2 2 0 0 1 .586-1.414l4.688-4.688A2 2 0 0 1 8.688 2h6.624a2 2 0 0 1 1.414.586l4.688 4.688A2 2 0 0 1 22 8.688v6.624a2 2 0 0 1-.586 1.414l-4.688 4.688a2 2 0 0 1-1.414.586H8.688a2 2 0 0 1-1.414-.586z"/><path d="m9 9 6 6"/>`
	iconLoaderCircle  = `<path d="M21 12a9 9 0 1 1-6.219-8.56"/>`
	iconX             = `<path d="M18 6 6 18"/><path d="m6 6 12 12"/>`
)

// icon returns the icon body of the toast kind, or "" for the default kind.
func (p ToastProps) icon() string {
	switch p.Toast.Kind {
	case gx.ToastSuccess:
		return iconCircleCheck
	case gx.ToastInfo:
		return iconInfo
	case gx.ToastWarning:
		return iconTriangleAlert
	case gx.ToastError:
		return iconOctagonX
	case gx.ToastLoading:
		return iconLoaderCircle
	}
	return ""
}

// iconClass returns the classes of the kind icon. The icon sits on the first
// text line, and the loading icon turns.
func (p ToastProps) iconClass() string {
	const base = "mt-0.5 size-4 shrink-0"
	if p.Toast.Kind == gx.ToastLoading {
		return base + " animate-spin motion-reduce:animate-none"
	}
	return base
}

// invoke returns the attribute that invokes the action of the toast. The
// adapter writes it. data-gx-close on the same button closes the toast.
func (p ToastProps) invoke() gx.Attrs {
	return gx.Attrs{gx.Invoke(p.Toast.Action.Method, string(p.Toast.Action.URL), "")}
}

// Render renders one pushed toast. An app passes it as gx.Config.Toast.
func Render(p gx.ToastPatch) gx.Node {
	return Toast(ToastProps{Toast: p})
}

